create table if not exists schedules(id uuid primary key default gen_random_uuid(),tenant_id uuid references tenants(id) on delete cascade,channel_id uuid not null references channels(id) on delete cascade,publish_at timestamptz not null,timezone text not null,enabled boolean not null default true,last_run_at timestamptz,next_run_at timestamptz,created_at timestamptz not null default now());
